import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Service;
import org.springframework.web.context.annotation.RequestScope;
import org.springframework.web.context.annotation.SessionScope;
import java.util.ArrayList;
import java.util.List;

@Service // default singleton scope
public class OrderService {
    private final OrderRepository repository;
    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }
}

@Service
@Scope("prototype") // a new instance every time
public class ReportGenerator {
    private String reportData; // stateful, so prototype is needed
}

@RequestScope // one instance per HTTP request
public class ShoppingCart {
    private List<String> items = new ArrayList<>();
}

@SessionScope // one instance per user session
public class UserPreferences {
    private String theme;
    private String language;
}
```

